constexpr Descriptor DescribeClientBoundary(ClientRole role) {
    return Describe({
        {static_cast<std::uint32_t>(ClientContract::Role), 0, static_cast<std::uint64_t>(role)},
        {static_cast<std::uint32_t>(ClientContract::CProfile), 0, ClientCProfile()},
        {static_cast<std::uint32_t>(ClientContract::EngineFunctions), 0, ClientFamily_EngineFunctions},
        {static_cast<std::uint32_t>(ClientContract::ClientFunctions), 0, ClientFamily_ClientFunctions},
        {static_cast<std::uint32_t>(ClientContract::NestedFunctions), 0, ClientFamily_NestedFunctions},
        {static_cast<std::uint32_t>(ClientContract::ExchangeFunctions), 0, ClientFamily_ExchangeFunctions},
        {static_cast<std::uint32_t>(ClientContract::ClientRecords), 0, ClientFamily_ClientRecords},
        {static_cast<std::uint32_t>(ClientContract::MovementRecords), 0, ClientFamily_MovementRecords},
        {static_cast<std::uint32_t>(ClientContract::ModelRecords), 0, ClientFamily_ModelRecords},
    });
}

constexpr Descriptor ClientModuleDescriptor = DescribeClientBoundary(ClientRole::Client);
constexpr Descriptor EngineClientDescriptor = DescribeClientBoundary(ClientRole::Engine);
static_assert(ClientModuleDescriptor.tableCount <= MaxTables, "Client catalog exceeds descriptor capacity");

